// Two layers live here. This package orchestrates: it builds a development CLI
// and engine out of the current source tree. The suites under testdata/ then run
// against what it built. Both import the Go client from this repo; this module
// exists to keep their test-only dependencies out of sdk/go.
//
// Orchestration talks to the engine-dev toolchain module through a client
// generated by `dagger api client` into internal/dagger/engine-dev. A generated
// client carries the whole core API alongside its bound module, so it also
// stands in for dagger.io/dagger throughout this package.
package e2e

import (
	"os"
	"testing"

	engineDev "github.com/dagger/dagger/sdk/go/e2e/internal/dagger/engine-dev"
)

type harness struct {
	// dag is the core API: containers, services, the workspace. It happens to be
	// the engine-dev client today, because a generated client carries the whole
	// core API alongside the module it binds. That is an accident of there being
	// one client; keep core calls on this field and module calls on the fields
	// below, and adding a second module later is a change of types here rather
	// than a rewrite of every call site.
	dag *engineDev.Client

	// engineDev is the engine-dev toolchain module: the dev engine and the
	// container it ships. Same object as dag until a generated client can share a
	// session (dagger/go-sdk#19), at which point it becomes a client of its own.
	engineDev *engineDev.EngineDev
}

func newHarness(t *testing.T) *harness {
	t.Helper()

	// Connecting a generated client also serves its bound module into the
	// session, which is what makes this work under `dagger api exec`. Workspace
	// modules normally appear in a session's API on their own, but the engine
	// decides whether to include them once, when it first sets up a client's
	// workspace, and caches that answer (ensureWorkspaceLoaded,
	// engine/server/session_workspaces.go); `dagger api exec` sets us up with
	// the built-in API only, and opting in afterwards does not re-run the
	// decision. Serving by module source sidesteps that, so the harness needs no
	// module config of its own.
	dag, err := engineDev.Connect(
		t.Context(),
		engineDev.WithLogOutput(os.Stderr),
	)
	if err != nil {
		t.Fatalf("connect orchestration client: %v", err)
	}
	t.Cleanup(func() {
		if err := dag.Close(); err != nil {
			t.Errorf("close orchestration client: %v", err)
		}
	})
	return &harness{dag: dag, engineDev: dag.EngineDev()}
}

// devCLIBinary lifts the CLI out of the engine container rather than building it
// from the cli-dev toolchain module directly.
//
// cli-dev would be the honest source, but a generated client is bound to one
// module and opens its own session when connected, so reaching it means a second
// client on a second session — and object IDs do not cross session boundaries,
// which is exactly what mounting this file into a container needs. Lifting it
// out of the engine works because engine-dev builds the container's CLI from
// cli-dev anyway. Revisit once dagger/go-sdk#18 and dagger/go-sdk#19 land.
func (h *harness) devCLIBinary() *engineDev.File {
	return h.engineDev.Container().File("/usr/local/bin/dagger")
}

func (h *harness) startDevEngine(t *testing.T, name string) (*engineDev.Service, string) {
	t.Helper()

	engine, err := h.engineDev.Service(name).Start(t.Context())
	if err != nil {
		t.Fatalf("start development engine: %v", err)
	}
	endpoint, err := engine.Endpoint(t.Context(), engineDev.ServiceEndpointOpts{Port: 1234, Scheme: "tcp"})
	if err != nil {
		t.Fatalf("resolve development engine endpoint: %v", err)
	}
	return engine, endpoint
}

func requireTargetExec(t *testing.T, target *engineDev.Container, operation string) {
	t.Helper()
	ctx := t.Context()
	stdout, err := target.Stdout(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stderr, err := target.Stderr(ctx)
	if err != nil {
		t.Fatal(err)
	}
	exitCode, err := target.ExitCode(ctx)
	if err != nil {
		t.Fatal(err)
	}

	t.Logf("%s stdout:\n%s", operation, stdout)
	if stderr != "" {
		t.Logf("%s stderr:\n%s", operation, stderr)
	}
	if exitCode != 0 {
		t.Fatalf("%s: exit code %d", operation, exitCode)
	}
}
